// Pixel load event listener
jQuery(document).on("pmw:load-pixels", () => {

	if (wpmDataLayer?.pixels?.vwo?.account_id && !wpmDataLayer?.pixels?.vwo?.loaded) {
		if (wpm.consent.canPixelBeFired("statistics", "VWO")) wpm.loadVwoPixel()
	}
})

// view order received page event
jQuery(document).on("pmw:browser:purchase", (event, payload) => {

	try {
		if (wpm.canNotFireVwoEvent()) return

		const vwoData = payload.pixels?.vwo;
		if (!vwoData) return;

		const data = [vwoData.event_type, vwoData.revenue_value];

		wpm.vwoLoaded().then(() => {
			window.VWO.push(data)
			pmw.console.log("VWO Pixel: track.revenueConversion event sent", data)
		})

	} catch (e) {
		console.error(e)
	}
})

